head.b:skin:
/* =========================================================================
 * ENGINEER'S SIDE CORNER - PREMIER MODERN TECH THEME
 * Complete Redesign with Rich Multi-Column Tech Footer & Dark Mode
 * ========================================================================= */
:root {
  --primary: #6366f1;
  --primary-hover: #4f46e5;
  --primary-glow: rgba(99, 102, 241, 0.25);
  --primary-soft: rgba(99, 102, 241, 0.08);
  --accent: #06b6d4;

  --bg-body: #f8fafc;
  --bg-card: #ffffff;
  --bg-card-subtle: #f1f5f9;
  --bg-header: rgba(255, 255, 255, 0.88);
  --bg-footer: #0f172a;
  --bg-footer-card: #1e293b;

  --text-primary: #0f172a;
  --text-secondary: #475569;
  --text-muted: #94a3b8;

  --text-footer: #94a3b8;
  --text-footer-heading: #f8fafc;
  --border-footer: rgba(255, 255, 255, 0.08);

  --border-color: #e2e8f0;
  --border-subtle: #f1f5f9;

  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-pill: 9999px;

  --shadow-sm: 0 1px 3px rgba(0,0,0,0.04);
  --shadow-card: 0 4px 20px -2px rgba(15, 23, 42, 0.06);
  --shadow-hover: 0 20px 35px -6px rgba(15, 23, 42, 0.12);

  --font-heading: 'Plus Jakarta Sans', -apple-system, sans-serif;
  --font-body: 'Inter', -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
}

[data-theme='dark'] {
  --bg-body: #0b0f19;
  --bg-card: #111827;
  --bg-card-subtle: #1e293b;
  --bg-header: rgba(11, 15, 25, 0.88);
  --bg-footer: #080c14;
  --bg-footer-card: #0f172a;

  --text-primary: #f8fafc;
  --text-secondary: #cbd5e1;
  --text-muted: #64748b;

  --border-color: #1f293d;
  --border-subtle: #192233;

  --shadow-sm: 0 1px 3px rgba(0,0,0,0.4);
  --shadow-card: 0 4px 20px -2px rgba(0, 0, 0, 0.4);
  --shadow-hover: 0 20px 35px -6px rgba(0, 0, 0, 0.6);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  background-color: var(--bg-body);
  color: var(--text-primary);
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
  transition: background-color 0.3s ease, color 0.3s ease;
}

a { color: inherit; text-decoration: none; transition: all 0.2s ease; }
img { max-width: 100%; height: auto; display: block; }

/* =========================================================================
 * CRITICAL: PURGE UNSTYLED ORPHAN / LEGACY BLOGGER WIDGETS
 * Hides the unstyled search, attribution, archive lists, and orphan links
 * ========================================================================= */
#main .widget:not(#Blog1),
.widget.BlogSearch,
.widget.Attribution,
.widget.BlogArchive,
.widget.ReportAbuse,
.widget.Profile,
.widget.LinkList,
.widget.ContactForm,
.widget.HTML:not(#sidebar-ad),
#BlogSearch1,
#Attribution1,
#BlogArchive1,
#HTML21,
#Label3,
#ReportAbuse1,
#Profile1,
#LinkList70,
#ContactForm1,
#LinkList71,
#LinkList74,
#LinkList76,
#Header1,
.attribution,
.quickedit {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
}

/* Reading Progress Bar */
.reading-progress-bar {
  position: fixed;
  top: 0;
  left: 0;
  height: 3px;
  background: linear-gradient(90deg, #6366f1, #06b6d4);
  width: 0%;
  z-index: 9999;
  transition: width 0.1s ease;
}

/* Layout Container */
.esc-container {
  max-width: 1260px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Header & Navigation */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--bg-header);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-color);
  padding: 14px 0;
  transition: all 0.3s ease;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.brand-area {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-logo-icon {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: linear-gradient(135deg, #6366f1 0%, #06b6d4 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 18px;
  box-shadow: 0 4px 12px rgba(99, 102, 241, 0.35);
  flex-shrink: 0;
}

.brand-text h1 {
  font-family: var(--font-heading);
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.15;
  background: linear-gradient(135deg, var(--text-primary) 30%, var(--primary) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.brand-text p {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-muted);
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.nav-center {
  display: flex;
  align-items: center;
  gap: 6px;
  list-style: none;
}

.nav-center a {
  font-family: var(--font-heading);
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-secondary);
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  gap: 6px;
}

.nav-center a:hover {
  color: var(--primary);
  background: var(--primary-soft);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.theme-toggle-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1px solid var(--border-color);
  background: var(--bg-card);
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  transition: all 0.2s ease;
}

.theme-toggle-btn:hover {
  color: var(--primary);
  border-color: var(--primary);
  transform: rotate(15deg);
}

.cta-portal-btn {
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 700;
  color: #fff;
  background: linear-gradient(135deg, #6366f1 0%, #4f46e5 100%);
  padding: 8px 18px;
  border-radius: var(--radius-pill);
  box-shadow: 0 4px 14px rgba(99, 102, 241, 0.3);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.cta-portal-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(99, 102, 241, 0.45);
  color: #fff;
}

/* Hero Section */
.hero-spotlight {
  position: relative;
  padding: 64px 0 48px;
  text-align: center;
  background: radial-gradient(circle at 50% 10%, rgba(99, 102, 241, 0.12) 0%, transparent 60%);
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 44px;
  overflow: hidden;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--primary-soft);
  color: var(--primary);
  border: 1px solid rgba(99, 102, 241, 0.25);
  padding: 5px 16px;
  border-radius: var(--radius-pill);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  margin-bottom: 20px;
}

.hero-headline {
  font-family: var(--font-heading);
  font-size: 46px;
  font-weight: 900;
  letter-spacing: -0.035em;
  line-height: 1.15;
  color: var(--text-primary);
  max-width: 820px;
  margin: 0 auto 16px;
}

.hero-headline span.gradient-text {
  background: linear-gradient(135deg, #6366f1 0%, #06b6d4 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.hero-subtext {
  font-size: 17px;
  color: var(--text-secondary);
  max-width: 640px;
  margin: 0 auto 28px;
  line-height: 1.6;
}

.quick-topics {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 10px;
}

.topic-pill {
  font-family: var(--font-heading);
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-secondary);
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  transition: all 0.2s ease;
}

.topic-pill:hover, .topic-pill.active {
  color: #fff;
  background: var(--primary);
  border-color: var(--primary);
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(99, 102, 241, 0.25);
}

/* Main Layout */
.layout-wrapper {
  display: flex;
  gap: 40px;
  margin-bottom: 70px;
}

.content-main {
  flex: 1 1 0%;
  min-width: 0;
}

.sidebar-pane {
  width: 350px;
  flex-shrink: 0;
}

/* Cards Grid */
.post-card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 30px;
}

.tech-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
  position: relative;
}

.tech-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-hover);
  border-color: rgba(99, 102, 241, 0.35);
}

.card-media-box {
  position: relative;
  width: 100%;
  height: 215px;
  overflow: hidden;
  background: #0f172a;
}

.card-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.tech-card:hover .card-img {
  transform: scale(1.08);
}

.card-badge-overlay {
  position: absolute;
  top: 14px;
  left: 14px;
  z-index: 2;
}

.card-badge {
  background: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 4px 12px;
  border-radius: var(--radius-pill);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.card-content {
  padding: 24px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.card-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: 12px;
}

.card-meta span {
  display: flex;
  align-items: center;
  gap: 5px;
}

.card-title {
  font-family: var(--font-heading);
  font-size: 19px;
  font-weight: 700;
  line-height: 1.38;
  color: var(--text-primary);
  margin-bottom: 12px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  transition: color 0.2s ease;
}

.card-title a:hover {
  color: var(--primary);
}

.card-snippet {
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.65;
  margin-bottom: 22px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  flex-grow: 1;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 16px;
  border-top: 1px solid var(--border-color);
  margin-top: auto;
}

.author-row {
  display: flex;
  align-items: center;
  gap: 9px;
}

.author-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--primary);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
}

.author-name {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-secondary);
}

.read-cta {
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 700;
  color: var(--primary);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: gap 0.2s ease;
}

.read-cta:hover {
  gap: 10px;
  color: var(--primary-hover);
}

/* Single Post */
.article-view-box {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 44px;
  margin-bottom: 40px;
}

.post-tag-list {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

.post-header-title {
  font-family: var(--font-heading);
  font-size: 38px;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.25;
  color: var(--text-primary);
  margin-bottom: 20px;
}

.post-info-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 32px;
}

.author-profile-chip {
  display: flex;
  align-items: center;
  gap: 12px;
}

.author-profile-chip .avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, #6366f1, #06b6d4);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-weight: 700;
  font-size: 16px;
}

.author-profile-chip .meta h5 {
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
}

.author-profile-chip .meta span {
  font-size: 12px;
  color: var(--text-muted);
}

.share-action-group {
  display: flex;
  align-items: center;
  gap: 8px;
}

.share-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid var(--border-color);
  background: var(--bg-card);
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 14px;
  transition: all 0.2s ease;
}

.share-btn:hover {
  color: #fff;
  background: var(--primary);
  border-color: var(--primary);
  transform: translateY(-2px);
}

.post-reading-content {
  font-size: 17px;
  line-height: 1.85;
  color: var(--text-secondary);
}

.post-reading-content h2, .post-reading-content h3 {
  font-family: var(--font-heading);
  font-weight: 800;
  color: var(--text-primary);
  margin: 36px 0 16px;
  letter-spacing: -0.02em;
}

.post-reading-content h2 { font-size: 26px; }
.post-reading-content h3 { font-size: 21px; }

.post-reading-content p { margin-bottom: 24px; }
.post-reading-content img {
  border-radius: var(--radius-md);
  margin: 30px auto;
  box-shadow: var(--shadow-card);
}

.author-bio-card {
  margin-top: 50px;
  padding: 28px;
  background: var(--bg-card-subtle);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  gap: 20px;
}

.author-bio-card .bio-avatar {
  width: 68px;
  height: 68px;
  border-radius: 50%;
  background: linear-gradient(135deg, #6366f1, #06b6d4);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 24px;
  font-weight: 800;
  flex-shrink: 0;
}

.author-bio-card h4 {
  font-family: var(--font-heading);
  font-size: 16px;
  font-weight: 800;
  margin-bottom: 6px;
}

.author-bio-card p {
  font-size: 13.5px;
  color: var(--text-secondary);
  line-height: 1.55;
}

/* Sidebar */
.sidebar-box {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 26px;
  margin-bottom: 30px;
}

.sidebar-box-title {
  font-family: var(--font-heading);
  font-size: 16px;
  font-weight: 800;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
  padding-bottom: 14px;
  border-bottom: 2px solid var(--border-color);
  margin-bottom: 20px;
}

.sidebar-box-title i { color: var(--primary); }

.about-widget-text {
  font-size: 13.5px;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 16px;
}

.social-link-row { display: flex; gap: 8px; }

.social-icon-btn {
  width: 34px;
  height: 34px;
  border-radius: var(--radius-sm);
  background: var(--bg-card-subtle);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  transition: all 0.2s ease;
}

.social-icon-btn:hover {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

.popular-post-row {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 0;
  border-bottom: 1px solid var(--border-color);
}

.popular-post-row:last-child { border-bottom: none; padding-bottom: 0; }
.popular-post-row:first-child { padding-top: 0; }

.popular-thumb-wrap {
  width: 70px;
  height: 60px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  flex-shrink: 0;
  position: relative;
  background: #0f172a;
}

.popular-thumb-wrap img { width: 100%; height: 100%; object-fit: cover; }

.popular-detail { flex: 1 1 0%; min-width: 0; }

.popular-title {
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--text-primary);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.popular-title:hover { color: var(--primary); }

.popular-date {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 4px;
}

.tag-cloud-wrap { display: flex; flex-wrap: wrap; gap: 8px; }

.tag-cloud-pill {
  font-family: var(--font-heading);
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  background: var(--bg-card-subtle);
  border: 1px solid var(--border-color);
  padding: 5px 12px;
  border-radius: var(--radius-pill);
  transition: all 0.2s ease;
}

.tag-cloud-pill:hover {
  color: #fff;
  background: var(--primary);
  border-color: var(--primary);
}

.newsletter-card {
  background: linear-gradient(135deg, rgba(99, 102, 241, 0.1) 0%, rgba(6, 182, 212, 0.1) 100%);
  border: 1px solid rgba(99, 102, 241, 0.25);
  border-radius: var(--radius-lg);
  padding: 24px;
  margin-bottom: 30px;
}

.newsletter-card h4 {
  font-family: var(--font-heading);
  font-size: 16px;
  font-weight: 800;
  color: var(--text-primary);
  margin-bottom: 6px;
}

.newsletter-card p {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.5;
  margin-bottom: 14px;
}

.newsletter-input-group { display: flex; gap: 8px; }

.newsletter-input {
  flex: 1;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 9px 12px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  outline: none;
}

.newsletter-input:focus { border-color: var(--primary); }

.newsletter-submit {
  background: var(--primary);
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  padding: 9px 14px;
  cursor: pointer;
  font-weight: 600;
  font-size: 13px;
  transition: background 0.2s;
}

.newsletter-submit:hover { background: var(--primary-hover); }

/* =========================================================================
 * 7. RICH 4-COLUMN TECH FOOTER
 * ========================================================================= */
.site-footer-rich {
  background: var(--bg-footer);
  color: var(--text-footer);
  border-top: 1px solid var(--border-footer);
  padding: 70px 0 0;
  margin-top: 80px;
  transition: background 0.3s;
}

.footer-columns-grid {
  display: grid;
  grid-template-columns: 2fr 1.2fr 1.2fr 1.6fr;
  gap: 40px;
  padding-bottom: 60px;
  border-bottom: 1px solid var(--border-footer);
}

.footer-col-brand .footer-brand-title {
  font-family: var(--font-heading);
  font-size: 22px;
  font-weight: 800;
  color: #fff;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.footer-col-brand .footer-brand-title i {
  color: var(--primary);
}

.footer-col-brand p {
  font-size: 14px;
  line-height: 1.7;
  color: #94a3b8;
  margin-bottom: 20px;
  max-width: 320px;
}

.footer-social-strip {
  display: flex;
  gap: 10px;
}

.footer-social-btn {
  width: 38px;
  height: 38px;
  border-radius: var(--radius-sm);
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #cbd5e1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  transition: all 0.25s ease;
}

.footer-social-btn:hover {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
  transform: translateY(-3px);
}

.footer-col-title {
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 800;
  color: var(--text-footer-heading);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 20px;
  position: relative;
  padding-bottom: 10px;
}

.footer-col-title::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 28px;
  height: 2px;
  background: var(--primary);
  border-radius: 2px;
}

.footer-nav-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.footer-nav-list li a {
  font-size: 14px;
  color: #94a3b8;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: all 0.2s ease;
}

.footer-nav-list li a:hover {
  color: #fff;
  transform: translateX(4px);
}

.footer-sub-card {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-md);
  padding: 20px;
}

.footer-sub-card p {
  font-size: 13px;
  color: #94a3b8;
  line-height: 1.6;
  margin-bottom: 14px;
}

.footer-sub-input-row {
  display: flex;
  gap: 8px;
}

.footer-sub-input-row input {
  flex: 1;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #fff;
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  outline: none;
}

.footer-sub-input-row input:focus {
  border-color: var(--primary);
}

.footer-sub-input-row button {
  background: var(--primary);
  color: #fff;
  border: none;
  padding: 10px 16px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
  transition: background 0.2s;
}

.footer-sub-input-row button:hover {
  background: var(--primary-hover);
}

/* Bottom Copyright Bar */
.footer-bottom-bar {
  padding: 26px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  font-size: 13px;
  color: #64748b;
}

.footer-bottom-bar a {
  color: #94a3b8;
}

.footer-bottom-bar a:hover {
  color: #fff;
}

.footer-bottom-links {
  display: flex;
  gap: 20px;
  list-style: none;
}

/* Responsive */
@media (max-width: 1024px) {
  .layout-wrapper { flex-direction: column; }
  .sidebar-pane { width: 100%; }
  .hero-headline { font-size: 36px; }
  .footer-columns-grid { grid-template-columns: 1fr 1fr; gap: 36px; }
}

@media (max-width: 680px) {
  .post-card-grid { grid-template-columns: 1fr; }
  .header-inner { flex-wrap: wrap; }
  .nav-center { display: none; }
  .hero-headline { font-size: 28px; }
  .article-view-box { padding: 22px; }
  .post-header-title { font-size: 26px; }
  .footer-columns-grid { grid-template-columns: 1fr; }
  .footer-bottom-bar { flex-direction: column; text-align: center; }
}

body.script:
//
function initTheme() {
  const savedTheme = localStorage.getItem('esc_theme') || (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
  applyTheme(savedTheme);
}

function applyTheme(theme) {
  if (theme === 'dark') {
    document.documentElement.setAttribute('data-theme', 'dark');
    const icon = document.getElementById('themeToggleIcon');
    if (icon) icon.className = 'fa-solid fa-sun';
  } else {
    document.documentElement.removeAttribute('data-theme');
    const icon = document.getElementById('themeToggleIcon');
    if (icon) icon.className = 'fa-solid fa-moon';
  }
  localStorage.setItem('esc_theme', theme);
}

function toggleDarkMode() {
  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
  applyTheme(isDark ? 'light' : 'dark');
}

initTheme();

window.addEventListener('scroll', () => {
  const bar = document.getElementById('readingProgressBar');
  if (!bar) return;
  const winScroll = document.documentElement.scrollTop || document.body.scrollTop;
  const height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
  if (height > 0) {
    const scrolled = (winScroll / height) * 100;
    bar.style.width = scrolled + '%';
  }
});
//
